#include "stdafx.h"#include "Client.h"#include "HcdPool.h"KHcdPool g_Pool;bool GetFirstACSObject(){  return g_Pool.GetFirstACSObject();}bool GetNextACSObject( DWORD & Type, void ** pData, char Name[256], char Data[256] ){  return g_Pool.GetNextACSObject( pData, Name, 256, Data, 256 );}bool ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData ){  return g_Pool.ShowACSObject( pInfo, hMainWnd, Name, pData );}bool KClient::GetFirstACSObject(){  m_nAcsFindStep = 0;  return true;}bool KClient::GetNextACSObject( void ** pData, char *Name, size_t sn, char *Data, size_t sd ){  if( 0==m_nAcsFindStep )  {    m_nAcsFindStep = -1;    strcpy_s( Name, sn, m_szObjName );    strcpy_s( Data, sd, "HCDRsu" );    return true;  }  else if( -1==m_nAcsFindStep )  {    m_nAcsFindStep = -2;    strcpy_s( Name, sn, ObjName );    strcpy_s( Data, sd, "HCDRsu" );    return true;  }  return false;}bool KClient::ShowACSObject( HWND hMainWnd, char * Name, void * pData ){  if( !strcmp(m_szObjName, Name) || !strcmp(ObjName, Name) )  {    __super::ShowObject( m_szObjName );    return true;  }  return false;}